import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.BlockEvent{Position: protocol.BlockPos{1, 2, 3}, EventType: 1, EventData: 0}
CHEST = bytes.fromhex("0204060200")

# generated by gophertunnel b8bd735:
# packet.BlockEvent{Position: protocol.BlockPos{-2, 300, 3}, EventType: -1, EventData: 200}
WIDE = bytes.fromhex("03d80406019003")

GOLDENS = [
    pytest.param(v2225.BlockEventPacket(pos=v2225.BlockPos(x=1, y=2, z=3), b0=1, b1=0), CHEST, id="chest"),
    pytest.param(v2225.BlockEventPacket(pos=v2225.BlockPos(x=-2, y=300, z=3), b0=-1, b1=200), WIDE, id="wide"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_block_event_is_packet_26(version):
    assert version.packets[26] is version.BlockEventPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_block_event_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_block_event_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
